        adl_transferring: document.getElementById('adl-transferring')?.value || 'Independent',
        adl_continence: document.getElementById('adl-continence')?.value || 'Independent',
        adl_feeding: document.getElementById('adl-feeding')?.value || 'Independent',
        iadl_shopping: document.getElementById('iadl-shopping')?.value || 'Independent',
        iadl_meals: document.getElementById('iadl-meals')?.value || 'Independent',
        iadl_housekeeping: document.getElementById('iadl-housekeeping')?.value || 'Independent',
        iadl_laundry: document.getElementById('iadl-laundry')?.value || 'Independent',
        iadl_transportation: document.getElementById('iadl-transportation')?.value || 'Independent',
        iadl_meds: document.getElementById('iadl-meds')?.value || 'Independent',
