        pe_cardio: document.getElementById('pe-cardio')?.value || '',
        pe_resp: document.getElementById('pe-resp')?.value || '',
        pe_abdomen: document.getElementById('pe-abdomen')?.value || '',
        pe_neuro: document.getElementById('pe-neuro')?.value || '',
        pe_skin: document.getElementById('pe-skin')?.value || '',

