                        if (addRecallBtn) {
                            addRecallBtn.onclick = () => {
                                openSetRecallModal(p, () => loadPatientRecalls());
                            };
                        }

                        // Wire Edit Recall buttons
                        sectionBody.querySelectorAll(".edit-recall-btn").forEach((btn) => {
                            btn.onclick = () => {
                                const rId = btn.getAttribute("data-id");
                                const recallObj = recallList.find((r) => r.id == rId);
                                if (recallObj) {
                                    openEditRecallModal(p, recallObj, () => loadPatientRecalls());
                                }
                            };
                        });

                        // Wire Schedule Appointment buttons
                        sectionBody
                            .querySelectorAll(".schedule-pat-recall-btn")
